"""Execute scripts generated by the C# ZBrush-only UI smoke with a fake API."""
import json
import runpy
import sys
import types
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
JOB_DIR = ROOT / "artifacts" / "zbrush-only-ui-smoke"
assert (JOB_DIR / "run_zbrush.py").is_file(), "Run ZBrushOnlyUiSmoke first"
calls = []
api = types.ModuleType("zbrush.commands")
api.exists = lambda path: path in {"Tool:Geometry:Divide", "Draw:Draw Size"}
api.press = lambda path: calls.append(("press", path))
api.set = lambda path, value: calls.append(("set", path, value))
api.get_active_tool_path = lambda: "Tool:Smoke"
api.get_subtool_count = lambda: 1
package = types.ModuleType("zbrush")
package.commands = api
sys.modules["zbrush"] = package
sys.modules["zbrush.commands"] = api
runpy.run_path(str(JOB_DIR / "run_zbrush.py"), run_name="__main__")
assert json.loads((JOB_DIR / "result.json").read_text(encoding="utf-8"))["ok"] is True
runpy.run_path(str(ROOT / "artifacts" / "zbrush-only-standalone-smoke.py"), run_name="__main__")
assert calls == [("press", "Tool:Geometry:Divide"), ("set", "Draw:Draw Size", 42.0)], calls
print("ZBRUSH_GENERATED_SCRIPT_PASS")
